// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // Add reward token via public entry
        c.addReward(rewardToken);
        // General rule: after addReward, rewardPeriodFinish for that token should be non-zero (since it was initialized)
        assertTrue(c.rewardPeriodFinish(rewardToken) != 0, "rewardPeriodFinish should be initialized after addReward");
    }
}

